def compute(vars):
    parent_value = vars["Overall Current Period Amount"]
    x0 = vars["Base Period Amount"]

    if x0 == 0:
        return None

    growth_rate = (parent_value - x0) / x0

    return {
        "value": growth_rate,
        "trace": {
            "Overall Current Period Amount": parent_value,
            "Base Period Amount": x0,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
